const e=JSON.parse('{"dette":{"name":"Debt crisis","tagline":"The coffers are empty and the rating agencies are sharpening their pencils.","briefing":{"title":"Red file: the debt {dePays} on the brink","text":"The Treasury has emptied its drawers, borrowing rates climb every morning and three rating agencies are threatening to downgrade {lePays}. You have ten quarters to repair the budget and revive the economy without setting the streets on fire. Austerity or growth: every trade-off has a price.","secretaire":"Mr President, the head of the Treasury is waiting in the corridor with a calculator and a box of tissues. I told him you had “a vision”."},"rules":{"sticky":{"label":"Agencies only upgrade drop by drop: budget gains are dampened."},"pressure":[{"label":"Interest on the debt"},{"label":"Anger at austerity"}],"lose":{"dette-defaut":{"reason":"Default: the markets turn off the tap and the Monetary Fund takes the keys to the Treasury."}}},"crises":{"dette-degradation":{"title":"Agencies downgrade the rating {dePays}","description":"Moody-Blues, Fiche & Cie and Pauvre’s publish on the same evening: the rating loses two notches. News channels show full-screen red arrows.","choices":{"economies":{"label":"Announce an immediate savings plan","description":"Reassures the markets, annoys everyone.","news":"Express savings plan: “every ministry will hand back its paperclips”."},"contester":{"label":"Challenge the agencies’ method","description":"Popular on TV, less so on the trading floor.","news":"“Grades given by people who never passed an exam”: the president attacks the agencies."},"creanciers":{"label":"Summon the creditors to the {palais}","description":"A dinner, canapés and a promise of seriousness.","news":"Creditors’ dinner: a sober menu, and a sober bill."}}},"dette-spreads":{"title":"Borrowing rates take off","description":"The gap with neighbouring countries hits a record. Every rate point costs a school a week, calculates a columnist who likes schools.","choices":{"patriotiques":{"label":"Issue patriotic bonds","description":"National savings to the rescue of the State.","news":"The “patriot bonds” are a hit: grandmothers subscribe en masse."},"fonds":{"label":"Ask the Monetary Fund for help","description":"The money arrives, and so does the supervision.","news":"The Monetary Fund lands with spreadsheets and walking shoes."},"maturite":{"label":"Lengthen the debt’s maturity","description":"Buy time, technical and discreet.","news":"The debt is extended: “our grandchildren will thank us”, the Treasury assures."}}},"dette-greve-fonctionnaires":{"title":"Civil servants strike against the pay freeze","description":"Counters closed, prefectures asleep, canteens in picnic mode: the civil service protests against the pay freeze.","choices":{"tenir":{"label":"Hold the freeze","description":"The budget breathes, the mood tightens.","news":"The freeze holds: counters stay closed “until further notice”."},"degeler":{"label":"Partially unfreeze","description":"Social peace has a cost.","news":"Partial thaw: civil servants return to work, the markets frown."},"symbole":{"label":"Freeze ministers’ pay first","description":"A symbol that costs nothing.","news":"Ministers give up 10% of their pay: some sell their official car."}}},"dette-retraites":{"title":"Express pension reform","description":"Creditors want “a strong signal”. The finance minister proposes raising the retirement age; the street proposes retiring the minister.","choices":{"force":{"label":"Force it through","description":"Fast, efficient, explosive.","news":"Reform passed overnight: the marches grow faster than the retirement age."},"negocier":{"label":"Negotiate with the unions","description":"Fewer savings, less damage.","news":"Deal struck at 4 am: everyone is “a little disappointed”, a sure sign of compromise."},"reporter":{"label":"Postpone it","description":"Markets hate waiting.","news":"The reform is “put on ice”: the agencies take note, literally."}}},"dette-investisseurs":{"title":"The great investor roadshow","description":"The Treasury organises a tour of financial centres to sell the debt {dePays}. A story is needed: seriousness, boldness or a promise?","choices":{"capitales":{"label":"Tour of the financial capitals","description":"Shake hands, many hands.","news":"Successful tour: investors leave with brochures and a little hope."},"croissance":{"label":"Sell future growth","description":"Contagious optimism, bold figures.","news":"“The land of opportunity”: the slogan raises smiles, subscriptions follow."},"promesse":{"label":"Promise a balanced budget within two years","description":"Committing… perhaps too much.","news":"Solemn promise of balance: economists dig out their 1998 charts."}}},"dette-tva":{"title":"The tax rise or the storm","description":"Billions are still missing. Three options on the table, none of them pleasant.","choices":{"tva":{"label":"Raise VAT by two points","description":"Guaranteed yield, pricier shopping trolleys.","news":"VAT up: the baguette gains two cents and plenty of comments."},"riches":{"label":"Tax the very highest incomes","description":"Fair, but capital has legs.","news":"Exceptional contribution from the richest: three yachts change flags."},"niches":{"label":"Cut tax loopholes","description":"Every loophole has its lobby.","news":"Loophole hunt: the corridors of the {parlement} fill with lobbyists."}}},"dette-banque-centrale":{"title":"The central bank hesitates to back you","description":"Without bond purchases, rates could spiral. The governor wants a sign, not a tweet.","choices":{"plaider":{"label":"Plead for massive support","description":"Effective if they listen.","news":"The central bank opens the floodgates (a little): rates breathe."},"independance":{"label":"Respect its independence","description":"Serious and patient.","news":"“Central bank independence is sacred”: partners hail your restraint."},"menacer":{"label":"Threaten to leave the monetary system","description":"A high-risk poker move.","news":"Exit threat: currency exchanges are stormed, and so are the markets."}}},"dette-manif":{"title":"The tide of saucepans","description":"Every evening at 8 pm, balconies bang saucepans against austerity. The racket can be heard all the way to the {palais}.","choices":{"syndicats":{"label":"Receive the unions","description":"Listening costs a little.","news":"Big social conference: the saucepans fall silent, for now."},"orage":{"label":"Let the storm pass","description":"Nothing moves, except the anger.","news":"The government “holds its course”: so do the saucepans."},"referendum":{"label":"Propose a referendum on the budget","description":"Hand back the floor… and the problem.","news":"Referendum announced: everyone becomes a public finance expert."}}},"dette-agences-revue":{"title":"Rating review by the agencies","description":"Last review before the end of the programme. Analysts want numbers, not adjectives.","choices":{"equilibre":{"label":"Present a balanced budget","description":"Rigour on display, tight smiles.","news":"Balanced budget presented: Pauvre’s praises “a sincere, almost touching effort”."},"reformes":{"label":"Bet on the reforms achieved","description":"Your record speaks for you.","news":"The agencies raise the outlook to “stable”: (lukewarm) champagne at the Treasury."},"rien":{"label":"Present nothing at all","description":"Bold. Very.","news":"No document submitted: the agencies speak of a “deafening silence”."}}},"dette-vote-budget":{"title":"The last-chance budget vote","description":"The final budget reaches the {parlement}. Rigour, compromise or stimulus: this vote will say what country you leave behind.","choices":{"rigueur":{"label":"Austerity budget","description":"Accounts first.","news":"Austerity budget narrowly passed: “brave”, say those who don’t pay."},"compromis":{"label":"Compromise budget","description":"Nobody is happy, everybody votes.","news":"Compromise budget: an amendment on roundabouts wins unanimity."},"relance":{"label":"Stimulus budget","description":"Bet on growth.","news":"Stimulus budget passed: markets raise an eyebrow, shopkeepers raise both arms."}}},"dette-fuite-capitaux":{"title":"Capital flight to tax havens","description":"Suitcases of cash cross the border in sports cars. Banks report transfers “to islands with unpronounceable names”.","choices":{"controle":{"label":"Impose capital controls","description":"Effective and brutal.","news":"Capital controls: cash machines cap withdrawals, customs officers search violin cases."},"amnistie":{"label":"Tax amnesty for repatriation","description":"The money returns, morality leaves.","news":"Tax amnesty: tax dodgers come home smiling."},"accord":{"label":"Sign an information-sharing agreement","description":"Slow but lasting.","news":"Information-sharing agreement signed: the islands with unpronounceable names grimace."}}},"dette-hopital":{"title":"Hospitals cut to the bone","description":"After three savings plans, a provincial hospital has replaced its stretchers with supermarket trolleys.","choices":{"rallonge":{"label":"Emergency top-up","description":"Health cannot wait.","news":"Hospital top-up: the trolleys go back to the supermarket."},"rationaliser":{"label":"Rationalise further","description":"Savings, and longer waits in A&E.","news":"New “rationalisation”: patients bring their own chair."},"dons":{"label":"Call for donations from billionaires","description":"Televised charity.","news":"Billionaires’ telethon: a scanner is now named after a yacht."}}},"dette-lingots":{"title":"Forgotten gold in the central bank’s vaults","description":"Looking for an old binder, an intern stumbles upon gold bars nobody had counted in decades.","choices":{"vendre":{"label":"Sell the gold","description":"Immediate cash.","news":"Gold sold: the intern is promoted to “special adviser for cellars”."},"garantie":{"label":"Keep it as collateral","description":"Creditors love gold bars.","news":"The gold serves as collateral: rates dip by a hair."},"musee":{"label":"Turn it into a museum","description":"Heritage first.","news":"“The national treasure” opens to the public: 200,000 visitors in a month."}}},"dette-scandale-ministre":{"title":"The budget minister and his hidden account","description":"The minister in charge of austerity held a “forgotten” account abroad. He swears he didn’t know that he knew.","choices":{"demission":{"label":"Immediate resignation","description":"Cut it short.","news":"The minister resigns “to focus on his defence and his accounts”."},"soutenir":{"label":"Back him publicly","description":"Costly loyalty.","news":"The president backs his minister: the polls no longer back the president."},"moralisation":{"label":"Pass an ethics law","description":"Turn the scandal into a reform.","news":"Ethics law: elected officials must declare even their piggy banks."}}},"dette-promesse-intenable":{"title":"The balanced-budget promise becomes untenable","description":"The figures won’t follow: the balance promised to investors recedes with every forecast.","choices":{"avouer":{"label":"Admit it and recalibrate","description":"Lose face, keep trust.","news":"“We used the wrong calculator”: the admission surprises, then reassures."},"maquiller":{"label":"Touch up the accounts a little","description":"Nobody will notice… except everybody.","news":"“Optimised” accounts: a journalist finds the moved decimal points."}}}},"decisions":{"dette-audit":{"title":"Truth audit of the accounts","description":"Put everything on the table: the truth hurts, but creditors love transparency.","news":"Truth audit published: 400 pages, 12 of which nobody dares read aloud."},"dette-privatisations":{"title":"Sell the family silver","description":"Privatise the national lottery, the motorways and the presidential stud farm: billions now, regrets later.","news":"Great State clearance sale: even the stud farm’s horses found buyers."},"dette-plan-relance":{"title":"Targeted stimulus plan","description":"Invest in building sites and training to regain growth, at the cost of a little debt.","delayed":[{"label":"The stimulus building sites pay off"}],"news":"Stimulus plan launched: cranes return to the skyline."}},"timeline":{"dette-t1":{"note":{"from":"Your private secretary","text":"The Treasury left a sticky note on your desk: “There is enough to pay civil servants until Thursday.” I made you a strong coffee."}},"dette-t2":{"appel":{"from":"The director of the (fictional) Monetary Fund","text":"We can help you. We love helping. You will simply have to leave us an office at the Treasury… and the keys."}},"dette-t3":{"news":"Ten-year rates hit a peak: economists fight over TV studio seats."},"dette-t5":{"appel":{"from":"The central bank governor","text":"I can promise nothing. But if you hold your accounts, I will hold my rates. And please avoid tweeting."}},"dette-t6":{"news":"The agencies will publish their review in three quarters: the countdown begins."},"dette-t8":{"note":{"from":"Your private secretary","text":"The {palais} neighbours are banging saucepans too. I shut the windows and put on classical music. Two quarters to go."}},"dette-t10":{"news":"Final quarter of the rescue plan: markets hold their breath."}},"objectives":{"dette-assainir":{"label":"Repair without breaking","description":"At the end: Budget ≥ 35 (out of the red) and Economy ≥ 45, without Cohesion ever falling below 25."},"dette-rue":{"label":"The street under control","description":"Cohesion never drops below 45 (end of each quarter)."},"dette-croissance":{"label":"Growth regained","description":"At the end: Economy ≥ 70 and Purchasing power ≥ 55."}},"endings":{"triomphe":{"title":"The budget miracle","text":"Accounts repaired, growth regained, streets calm: the agencies upgrade the rating and economics textbooks give you a sidebar.","une":{"titre":"{LePays} climbs back: rating upgraded, president hailed","chapo":"Ten quarters after the brink, creditors are smiling and the saucepans are put away."}},"succes":{"title":"Saved by a whisker","text":"The budget holds and the economy is picking up. Not everything is solved, but the country is no longer on the brink of default.","une":{"titre":"Debt: {lePays} avoids the worst","chapo":"Markets grant a reprieve. Experts speak of “a serious recovery, without the glitter”."}},"echec":{"title":"The plan was not enough","text":"The country avoided bankruptcy, but the accounts are still in the red or the street boiled over. The next government will inherit the file… and the sticky note.","une":{"titre":"Debt: the unfinished rescue","chapo":"Neither bankruptcy nor recovery: {lePays} stays under the agencies’ watch."}},"chute":{"title":"The fall","text":"The government falls before the end of the rescue plan. The creditors, however, are still here.","une":{"titre":"Political bankruptcy: the president takes the debt down with him","chapo":"The Monetary Fund sets up its offices. The cellar intern keeps his job."}}}},"pandemie":{"name":"Pandemic","tagline":"An unknown virus, hospitals under strain, and a country watching you.","briefing":{"title":"Health alert: a new virus reaches {lePays}","text":"An unprecedented virus has just been detected at {capitale} airport. Hospital beds, lockdowns, schools, vaccines, international cooperation: every decision trades health against cohesion and the economy. Hold for ten quarters without letting any gauge sink into the red.","secretaire":"Mr President, I ordered hand sanitiser for the whole floor. The health adviser is already wearing two masks and talking about “waves”. I don’t think he means surfing."},"rules":{"sticky":{"label":"Trust returns slowly: Cohesion gains are dampened."},"pressure":[{"label":"Epidemic wave: hospitals overwhelmed"},{"label":"New wave"},{"label":"Economic after-effects of the epidemic"}],"lose":{"pandemie-hopital":{"reason":"Hospital collapse: the army takes over the health crisis and asks you to step aside."}}},"crises":{"pandemie-patient-zero":{"title":"An unknown virus at {capitale} airport","description":"One feverish traveller, then ten, then a hundred. Doctors talk of a new respiratory virus, social networks of a pigeon conspiracy.","choices":{"frontieres":{"label":"Close the borders","description":"Radical, but the neighbours grumble.","news":"Borders closed: customs officers take lorries’ temperatures."},"tracer":{"label":"Isolate cases and trace","description":"Methodical and costly.","news":"Test, trace, isolate: health investigators ring every doorbell."},"grippette":{"label":"Reassure: “just a little flu”","description":"Popular… for now.","news":"“A little flu”: the presidential phrase loops endlessly, not necessarily for good reasons."}}},"pandemie-confinement":{"title":"Should the country be locked down?","description":"Intensive care units are filling up. Epidemiologists demand a lockdown, shopkeepers a prayer.","choices":{"strict":{"label":"Strict lockdown","description":"The epidemic retreats, and so does the economy.","news":"Nationwide lockdown: the country discovers home-made bread and video calls in pyjamas."},"couvre-feu":{"label":"Targeted curfew","description":"An imperfect compromise.","news":"8 pm curfew: joggers run much faster at 7:55 pm."},"ouvert":{"label":"Stay open, appeal to responsibility","description":"The economy runs, the hospitals cough.","news":"“Be responsible”: the country stays open, A&E overflows."}}},"pandemie-masques":{"title":"The mask shortage","description":"The strategic stocks were “rationalised” ten years ago. Twelve masks and a user manual remain.","choices":{"requisition":{"label":"Requisition textile factories","description":"Make them at home.","news":"Lingerie factories make masks: some are in lace."},"acheter":{"label":"Buy at any price abroad","description":"Fast, ruinous.","news":"Masks bought on a foreign tarmac, in cash, on the sly."},"inutiles":{"label":"Explain that masks are useless","description":"Cheap and debatable.","news":"The spokesperson swears masks are useless… while wearing a mask."}}},"pandemie-ecoles":{"title":"Reopen the schools?","description":"Parents work from home with children on their laps. Teachers’ unions want guarantees, paediatricians want playtime.","choices":{"protocole":{"label":"Reopen with a strict protocol","description":"Families breathe, so does the virus.","news":"Back to class: a 63-page protocol, 4 of them on hand-washing."},"fermees":{"label":"Keep schools closed","description":"Caution, exhausted families.","news":"Schools closed: parents rediscover fractions, and despair."},"tablettes":{"label":"Remote lessons, free tablets","description":"Modern and costly.","news":"A tablet for every pupil: half are used for games, so is the other half."}}},"pandemie-vaccin":{"title":"The vaccine race","description":"Three laboratories announce promising results. Rich countries are already signing giant pre-orders.","choices":{"prefinancer":{"label":"Pre-fund three laboratories","description":"Be served first.","news":"Massive pre-funding: the first doses will arrive “before the holidays”."},"groupe":{"label":"Join the international joint purchase","description":"Solidarity, a little slower.","news":"Joint purchase: doses will be shared “fairly, to the decimal point”."},"attendre":{"label":"Wait for other countries’ vaccine","description":"Cheap, risky.","news":"“We shall see”: {lePays} waits its turn at the global counter."}}},"pandemie-passe":{"title":"The health pass divides","description":"Should proof of vaccination be required for restaurants, cinemas, markets? Café terraces are at each other’s throats.","choices":{"partout":{"label":"Pass required everywhere","description":"Effective, divisive.","news":"Pass everywhere: the country splits between those who scan and those who shout."},"cible":{"label":"Pass for large gatherings only","description":"Fragile balance.","news":"Targeted pass: concerts filter, markets breathe."},"aucun":{"label":"No pass","description":"Freedom, and a health gamble.","news":"No pass: “let’s trust common sense”, says the president, fingers crossed."}}},"pandemie-variant":{"title":"A new, more contagious variant","description":"The “Delta-Plus-Plus” variant is spreading. Experts advise caution, café terraces advise the opposite.","choices":{"reconfiner":{"label":"Lock down again","description":"Safe, exhausting.","news":"Second lockdown: the country digs out the thousand-piece puzzles."},"rappel":{"label":"Massive booster campaign","description":"Fast, costly.","news":"Boosters for all: vaccination centres open even in gyms."},"vivre":{"label":"“Live with the virus”","description":"Economy first.","news":"“Living with it”: the virus is living very well with us."}}},"pandemie-soignants":{"title":"Exhausted carers threaten to resign","description":"After months of shifts, nurses lay their scrubs in front of prefectures. The 8 pm applause is no longer enough.","choices":{"revaloriser":{"label":"Raise salaries","description":"Fair and costly.","news":"Historic pay rise for carers: the scrubs return to duty."},"medailles":{"label":"Medals and applause","description":"Symbolic, insufficient.","news":"Medal of courage: carers pin it… on the ministry’s door."},"recruter":{"label":"Recruit carers from abroad","description":"Fast, criticised.","news":"International recruitment: neighbouring countries protest against “scrub poaching”."}}},"pandemie-reouverture":{"title":"The great reopening","description":"The numbers finally fall. The country wants to go out, dance, spend — sometimes all at once.","choices":{"fete":{"label":"A national reopening festival","description":"Collective joy, a small risk.","news":"Reopening festival: people kiss, think twice, then kiss again."},"graduel":{"label":"Gradual reopening","description":"Prudence pays.","news":"Step-by-step reopening: the schedule fits on one page, a first."},"cheques":{"label":"Kick-start with restaurant vouchers","description":"The terraces thank you.","news":"Restaurant vouchers for all: chefs don’t know which way to turn."}}},"pandemie-commission":{"title":"The commission of inquiry","description":"The {parlement} opens an inquiry into the handling of the crisis. Hearings will be broadcast live.","choices":{"cooperer":{"label":"Cooperate fully","description":"Transparency reassures.","news":"The president testifies: “We did our best, and sometimes our less-than-best.”"},"secret":{"label":"Invoke health secrecy","description":"Nothing leaks, everything is guessed.","news":"“Health secrecy”: hearings take place behind a curtain, literally."},"ministre":{"label":"Pin it on the health minister","description":"A fuse blows.","news":"The health minister resigns “for health reasons”."}}},"pandemie-complot":{"title":"Conspiracy theories go viral","description":"An influencer claims the virus spreads through TV aerials. His video beats the evening news.","choices":{"verifier":{"label":"Fact-checking campaign","description":"Patient, useful.","news":"“True or false?” campaign: TV aerials are cleared."},"ignorer":{"label":"Ignore it","description":"The buzz fades… or not.","news":"The government ignores the rumour: the rumour does not ignore it."},"inviter":{"label":"Invite the influencer to the {palais}","description":"Bold, risky.","news":"The influencer at the {palais}: he films the curtains “to prove they exist”."}}},"pandemie-papier":{"title":"Run on toilet paper","description":"Shelves are empty, trolleys full. A sociologist speaks of “primal fear”, a roll in hand.","choices":{"rationner":{"label":"Ration: two packs per household","description":"Order and grumbling.","news":"Rationing: large families show their family record book at the checkout."},"production":{"label":"Double paper-mill output","description":"The market calms down.","news":"Paper mills run day and night: the roll crisis is resolved."},"message":{"label":"Soothing presidential address","description":"Tone is everything.","news":"“There will be enough for everyone”: the phrase becomes a meme, shelves refill."}}},"pandemie-frontieres":{"title":"Neighbouring countries close their borders","description":"Lorries stuck, cross-border workers stranded, cheeses suffering: the neighbours lower the barriers.","choices":{"couloirs":{"label":"Negotiate health corridors","description":"Effective diplomacy.","news":"Health corridors open: cheeses get through, viruses less so."},"fermer":{"label":"Close ours too","description":"Reciprocity.","news":"Reciprocal closure: cross-border workers sleep at the office."},"protester":{"label":"Protest officially","description":"Symbolic.","news":"Official protest: ambassadors exchange notes two metres apart."}}},"pandemie-teletravail":{"title":"Remote work everywhere","description":"Offices are empty, so are the traffic jams. Companies discover you can work in slippers.","choices":{"encourager":{"label":"Encourage it for good","description":"Fewer commutes, more loneliness.","news":"Remote work encouraged: traffic jams become a memory."},"retour":{"label":"Back to the office","description":"Social ties, and commuting.","news":"Back to the office: the coffee machines are moved."},"droit":{"label":"Write a right to remote work into law","description":"Social progress.","news":"Right to remote work: the slipper becomes a national symbol."}}},"pandemie-deni":{"title":"Hospitals overflow: denial no longer holds","description":"The “little flu” fills intensive care. Videos of the presidential phrase circulate with sirens in the background.","choices":{"meaculpa":{"label":"Televised mea culpa","description":"Humility heals a little.","news":"“I was wrong”: the presidential admission breaks viewing records."},"voyageurs":{"label":"Blame foreign travellers","description":"Easy, unfair.","news":"Foreign travellers blamed: embassies summon our ambassadors."}}}},"decisions":{"pandemie-lits":{"title":"Emergency plan: 10,000 beds","description":"Field hospitals, reservists, requisitioned clinics: hold the wave, whatever it costs.","news":"10,000 beds in a month: a former conference centre becomes a hospital."},"pandemie-cooperation":{"title":"International vaccine alliance","description":"Share research, doses and data with other countries: slower for yourself, safer for all.","news":"{LePays} launches a vaccine alliance: 40 countries sign, two ask questions."},"pandemie-cheque":{"title":"Survival cheque for shops","description":"Help small shops and families get through the closures.","news":"Survival cheque paid: booksellers reopen through the window."}},"timeline":{"pandemie-t1":{"note":{"from":"Your private secretary","text":"The health adviser put on a mask. Then two. He asks whether the cabinet meeting can be held by phone."}},"pandemie-t2":{"news":"Hospitals trigger the emergency plan: non-urgent operations are postponed."},"pandemie-t3":{"appel":{"from":"The director of the (fictional) World Health Organisation","text":"The world is watching how {lePays} handles the wave. Share your data, and we will share ours. And wash your hands."}},"pandemie-t5":{"appel":{"from":"The boss of a big laboratory","text":"We will have a vaccine. Above all we need a signature, a cheque and a photo with you."}},"pandemie-t7":{"news":"A new variant detected: epidemiologists learn the Greek alphabet at high speed."},"pandemie-t8":{"note":{"from":"Your private secretary","text":"The nurses from the nearby hospital left flowers and a letter. The letter is less kind than the flowers."}}},"objectives":{"pandemie-tenir":{"label":"Hold until the end","description":"Security (hospital capacity) never goes into the red, and at the end no gauge is below 25 (not even the Budget)."},"pandemie-calme":{"label":"A calm country","description":"Cohesion never drops below 42: little anger in the streets."},"pandemie-ensemble":{"label":"Vaccines for everyone","description":"Launch the international vaccine alliance, with International ≥ 60 at the end."}},"endings":{"triomphe":{"title":"The country held, together","text":"Hospitals never broke, the streets stayed calm and {lePays} shared its vaccines. Your handling is cited as an example, even in neighbouring countries.","une":{"titre":"Pandemic: {lePays} emerges from the crisis head held high","chapo":"Ten quarters of waves, no shipwreck: the president hailed by carers and neighbours."}},"succes":{"title":"The wave has passed","text":"The country leaves the epidemic with no gauge in the red. The scars are there, but the system held.","une":{"titre":"End of the epidemic: the country breathes again","chapo":"Masks put away, terraces full: time for relief… and for inquiries."}},"echec":{"title":"A limping way out","text":"The virus retreats, but the country comes out damaged: at least one gauge is in the red, or hospitals came close to breaking.","une":{"titre":"After the virus, the hangover","chapo":"The pandemic recedes; the bills and the anger remain."}},"chute":{"title":"Swept away by the wave","text":"The health crisis got the better of your government before the epidemic ended.","une":{"titre":"President swept away by the pandemic","chapo":"A crisis government takes over. The health adviser now wears three masks."}}}},"krach":{"name":"Crash","tagline":"The stock market collapses, banks totter, and your citizens’ savings with them.","briefing":{"title":"Black Monday: the stock market {dePays} loses 30%","text":"A bubble of “innovative” loans has just burst. Fragile banks, worried savers, cascading layoffs: you have eight quarters to stabilise the economy and purchasing power. Save the banks or regulate them? Both if possible, but not at the same price.","secretaire":"Mr President, the economy minister called three times. The third time, he was crying. I wrote “urgent” and underlined it twice."},"rules":{"sticky":{"label":"Confidence cannot be decreed: Economy gains are dampened."},"pressure":[{"label":"Cascading layoffs"}],"lose":{"krach-depression":{"reason":"Great depression: the economy collapses and the street demands a government of national salvation."}}},"crises":{"krach-lundi-noir":{"title":"Black Monday: the stock market plunges","description":"Screens are red from floor to ceiling. A trader was seen crying in a fountain.","choices":{"fermer":{"label":"Close the stock exchange for three days","description":"Cut the power to avoid the fire.","news":"Stock exchange closed: traders discover board games."},"discours":{"label":"Address of confidence to the nation","description":"Words can calm markets… sometimes.","news":"“The fundamentals are sound”: the presidential speech steadies prices (a little)."},"racheter":{"label":"Buy shares with public money","description":"Spectacular and expensive.","news":"The State buys en masse: the sovereign fund becomes the country’s top shareholder."}}},"krach-ruee":{"title":"Run on the Banque Populeuse","description":"A three-kilometre queue snakes outside the branches. Some customers brought tents.","choices":{"garantie":{"label":"Guarantee all deposits","description":"The State stands guarantor, and so does the budget.","news":"“Not a cent will be lost”: the tents are folded away."},"limiter":{"label":"Limit withdrawals","description":"The bank holds, anger rises.","news":"Withdrawals capped: cash machines become protest sites."},"laisser":{"label":"Let the bank fall","description":"Market morality, brutal version.","news":"The Banque Populeuse closes: its customers retrain as petitioners."}}},"krach-sauvetage":{"title":"Should Crédit Hasardeux be saved?","description":"The country’s second-largest bank bet on “structured products” nobody understands, not even the bank.","choices":{"renflouer":{"label":"Bail it out, no strings attached","description":"The system holds, taxpayers grind their teeth.","news":"Unconditional bailout: the bank’s bosses keep their golden parachutes."},"nationaliser":{"label":"Nationalise","description":"The State as banker.","news":"Crédit Hasardeux nationalised: from now on it will be called “Crédit Raisonnable”."},"faillite":{"label":"Organise an orderly bankruptcy","description":"Punish, at the risk of contagion.","news":"Orderly bankruptcy: shareholders pay, savers are protected, markets tremble."}}},"krach-licenciements":{"title":"Giant layoff plan at a carmaker","description":"The country’s top carmaker announces 20,000 job cuts. Factories stop, suppliers totter.","choices":{"partiel":{"label":"State-funded short-time work","description":"Keep the skills.","news":"Short-time work: workers keep their badges and their pay."},"prime":{"label":"Car scrappage bonus","description":"Boost sales, at the cost of the air.","news":"Scrappage bonus: old cars queue at the scrapyard."},"marche":{"label":"Let the market decide","description":"The market decides, workers suffer.","news":"“The market will adjust”: factories close, roundabouts fill up."}}},"krach-sommet":{"title":"Emergency summit of the big economies","description":"The leaders of the great powers meet by video call. Some forgot to mute their microphones.","choices":{"relance":{"label":"Argue for a coordinated stimulus","description":"Stronger together.","news":"Coordinated stimulus adopted: the final communiqué fits on three pages, a record."},"paradis":{"label":"Defend friendly tax havens","description":"Cynical but lucrative.","news":"{LePays} defends “alternative financial centres”: the other leaders turn off their cameras."},"taxe":{"label":"Propose a global transaction tax","description":"Ambitious and popular.","news":"Global tax proposed: bankers cry scandal, public opinion applauds."}}},"krach-immobilier":{"title":"The housing bubble bursts","description":"Prices fall, indebted homeowners can no longer repay. Bailiffs have work for ten years.","choices":{"moratoire":{"label":"Moratorium on repossessions","description":"Protect families.","news":"Repossession moratorium: bailiffs take forced holidays."},"racheter":{"label":"Buy up the bad loans","description":"Clean up bank balance sheets.","news":"“Bad bank” created: a complicated name for a simple bill."},"baisse":{"label":"Let prices fall","description":"Painful, healthy in the long run.","news":"Prices fall: young people can finally buy… if they find a loan."}}},"krach-bonus":{"title":"Rescued bankers pay themselves bonuses","description":"Barely bailed out, several banks announce record bonuses. Savers struggle to applaud.","choices":{"taxer":{"label":"Tax these bonuses at 90%","description":"Immediate justice.","news":"Bonuses taxed at 90%: traders discover frugality."},"rembourser":{"label":"Demand repayment of the aid","description":"Fair.","news":"Repayment demanded: banks hand the money back, reluctantly and in small notes."},"contrat":{"label":"Do nothing: “it’s contractual”","description":"Legally sound, politically suicidal.","news":"“It’s contractual”: the presidential phrase is printed on placards."}}},"krach-reprise":{"title":"The first signs of recovery","description":"Orders pick up, the stock market climbs a notch. Economists hesitate between “recovery” and “technical rebound”.","choices":{"accelerer":{"label":"Speed up the stimulus","description":"Strike while the iron is hot.","news":"Stimulus accelerated: cranes reappear in the cities."},"rembourser":{"label":"Pay back the crisis debt","description":"Budget prudence.","news":"Priority to repayment: the rating agencies nod."},"fete":{"label":"Celebrate the recovery","description":"Good for morale.","news":"“The worst is behind us”: the president pops the (national) champagne."}}},"krach-epargnants":{"title":"Savers protest in front of the banks","description":"Placards, whistles and calculators held high: small savers demand an account.","choices":{"recevoir":{"label":"Receive a delegation","description":"Listening calms things down.","news":"Delegation received at the {palais}: they are served coffee and guarantees."},"disperser":{"label":"Disperse the protest","description":"Order, at the price of image.","news":"Protest dispersed: images of pensioners being chased go around the world."},"mediateur":{"label":"Create a national banking ombudsman","description":"One more institution, a useful one.","news":"Banking ombudsman created: 300,000 cases filed in the first week."}}},"krach-trader":{"title":"A trader admits betting everything on the wrong horse","description":"A young trader admits committing 50 billion on a “hunch”. He asks if it’s serious.","choices":{"proces":{"label":"Exemplary trial","description":"Deliver justice and make it a symbol.","news":"Trial of the rogue trader: he pleads “enthusiasm”."},"discretion":{"label":"Settle it quietly","description":"Markets prefer silence.","news":"Settled behind the scenes: the press speaks of “omertà in a suit”."},"ministre":{"label":"Give him a Ministry of Humour","description":"Nobody saw it coming.","news":"Surreal appointment: the trader becomes “Junior Minister for Derision”."}}},"krach-crypto":{"title":"The “BitBaguette” digital currency collapses","description":"Influencers’ favourite cryptocurrency loses 99% overnight. Its founders are unreachable, “on a spiritual retreat”.","choices":{"interdire":{"label":"Ban cryptocurrencies","description":"Radical.","news":"Cryptocurrencies banned: influencers discover savings accounts."},"indemniser":{"label":"Compensate small holders","description":"Generous, debatable.","news":"Small holders compensated: BitBaguette is renamed “BitRusk”."},"reguler":{"label":"Finally regulate","description":"Serious, lasting.","news":"Crypto regulation: platforms must display “risk of losing everything”."}}},"krach-pme":{"title":"Small businesses strangled by credit","description":"Banks no longer lend. Bakers, mechanics and start-ups wait for answers that never come.","choices":{"pret":{"label":"State-guaranteed loans","description":"Credit flows again.","news":"Guaranteed loans: bakers relight the ovens."},"pression":{"label":"Lean on the banks","description":"Free, uncertain.","news":"The summoned bankers promise to “look at applications kindly”."},"charges":{"label":"Defer social charges","description":"A breath of oxygen.","news":"Charges deferred: small firms breathe, social security holds its breath."}}},"krach-pensions":{"title":"Pension funds are melting","description":"Supplementary pensions have lost a third of their value. Pensioners do their sums, and there are many of them.","choices":{"garantir":{"label":"Guarantee pensions","description":"Reassuring and costly.","news":"Pensions guaranteed: pensioners resume their cruises."},"geler":{"label":"Freeze indexation","description":"Budget first.","news":"Indexation frozen: pensioners march with walking frames, very determined."},"fonds":{"label":"Create a solidarity fund","description":"Share the effort.","news":"Solidarity fund: large fortunes are “invited” to contribute."}}},"krach-matelas":{"title":"Rush for gold and mattresses","description":"Citizens withdraw their savings to hide them under the mattress. Sales of thick mattresses soar.","choices":{"bons":{"label":"Issue national savings bonds","description":"Channel fear towards the State.","news":"National savings bonds: mattresses empty in favour of the Treasury."},"rassurer":{"label":"Reassure on television","description":"Talk, again.","news":"The president shows his own bank statement on TV: record audience."},"silence":{"label":"Say nothing","description":"Silence worries.","news":"Silence at the top: mattresses get thicker."}}},"krach-rechute":{"title":"The bailed-out bank relapses","description":"Crédit Hasardeux, saved with no strings attached, has resumed its bets. It asks for a second, “very small” top-up.","choices":{"encore":{"label":"Bail it out again","description":"A bottomless pit.","news":"Second bailout: the press speaks of a “bank on a drip”."},"demanteler":{"label":"Break up the bank","description":"Cut the evil at the root.","news":"Crédit Hasardeux broken up: its branches become cafés."}}}},"decisions":{"krach-separation":{"title":"Separate retail and investment banking","description":"Savers’ deposits will no longer be used to play the casino: the reform that angers banks and reassures everyone.","news":"Banking separation passed: the casino and the counter will no longer share a till."},"krach-grands-travaux":{"title":"Great works: a hundred bridges for the future","description":"Revive jobs through public investment: bridges, rails, school renovation.","delayed":[{"label":"The great works run at full speed"}],"news":"A hundred bridges launched: some span rivers, others controversies."},"krach-taxe-bonus":{"title":"Windfall tax on financial profits","description":"Make those who gambled and won before the crash contribute.","news":"Tax on financial profits: traders try to declare their bonuses as “comfort expenses”."}},"timeline":{"krach-t1":{"note":{"from":"Your private secretary","text":"The switchboard is jammed: savers are asking whether their savings account “still exists”. I said yes. I hope I was right."}},"krach-t2":{"appel":{"from":"The central bank governor","text":"I am injecting liquidity, but I cannot do everything. Protect deposits, and fast: a queue in front of a bank is contagious."}},"krach-t3":{"news":"Unemployment rises for a third month: job centres open on Sundays."},"krach-t4":{"appel":{"from":"The president of the employers’ federation","text":"Our companies are holding on by a thread. Give us credit, or at least time. Both would be perfect."}},"krach-t7":{"note":{"from":"Your private secretary","text":"A banker sent a fruit basket to thank you for the rescue. I gave the fruit to the staff and kept the card for the archives."}},"krach-t8":{"news":"Last quarter before the crisis review: economists sharpen their curves."}},"objectives":{"krach-stabiliser":{"label":"Stabilise the country","description":"At the end: Economy ≥ 52 and Purchasing power ≥ 50."},"krach-reformes":{"label":"Reform finance","description":"Separate the banks and enact at least three laws during the crisis."},"krach-epargne":{"label":"Savings protected","description":"Guarantee deposits during the bank run, with Budget ≥ 35 at the end."}},"endings":{"triomphe":{"title":"The saviour of savings","text":"The economy is back, savings are intact and finance is finally regulated. Textbooks will talk about the “{pays} model”.","une":{"titre":"After the crash, {lePays} leads by example","chapo":"Banks regulated, savers reassured, growth regained: the president turned panic into reform."}},"succes":{"title":"The storm has passed","text":"The economy and purchasing power are stabilised. Traders are a little less tanned, savers a little calmer.","une":{"titre":"Crash: the recovery is confirmed","chapo":"Eight quarters after Black Monday, stock exchange screens turn green again."}},"echec":{"title":"A make-believe recovery","text":"The banking system held, but the economy or purchasing power did not recover. The crisis will leave lasting scars.","une":{"titre":"Crash: the convalescence drags on","chapo":"Banks saved, households forgotten: the country is still waiting for the promised recovery."}},"chute":{"title":"Swept away by the crash","text":"The financial crisis brought down your government before the recovery.","une":{"titre":"The crash takes down the president","chapo":"A national unity government takes over the file. BitBaguette, however, is not coming back."}}}},"mondial":{"name":"Football World Cup","tagline":"The country hosts the World Cup: stadiums, crowds, and a nation hanging on a ball.","briefing":{"title":"{LePays} hosts the World Cup","text":"Stadiums are under construction, supporters from all over the world are booking tickets and the national team is aiming for the title. Budget, security, international image: you have eight quarters until the closing ceremony. Match results don’t depend on you… well, not entirely.","secretaire":"Mr President, the federation delivered your official jersey. It fits, except for the sleeves. I also received 4,000 requests for final tickets, including one from your mother-in-law."},"rules":{"sticky":{"label":"Construction overruns cannot be recouped: Budget gains are dampened."},"pressure":[{"label":"Stadium construction sites"},{"label":"Tournament crowds"}],"lose":{"mondial-retrait":{"reason":"Security chaos: the international federation strips {lePays} of the tournament."}}},"matches":{"mondial-match-ouverture":{"label":"Opening match against Borduria","adversaire":"Borduria","win":{"news":"Opening win against Borduria: the country sings in the streets until dawn."},"lose":{"news":"Opening defeat against Borduria: the mood collapses like a soufflé."}},"mondial-match-huitieme":{"label":"Round of 16 against Syldavia","adversaire":"Syldavia","win":{"news":"Through to the quarters after beating Syldavia: the car horns never stop."},"lose":{"news":"Knocked out by Syldavia in the round of 16: the country switches off the TV in silence."}},"mondial-match-quart":{"label":"Quarter-final against Ruritania","adversaire":"Ruritania","win":{"news":"Semi-final! Ruritania beaten on penalties, the goalkeeper becomes a national hero."},"lose":{"news":"Quarter-final exit against Ruritania: “a fine run”, commentators console themselves."}},"mondial-match-demi":{"label":"Semi-final against Groland","adversaire":"Groland","win":{"news":"Into the final! Groland goes down, the whole country loses its voice."},"lose":{"news":"Beaten by Groland in the semi-final: the pride remains, the title slips away."}},"mondial-match-finale":{"label":"Final against Bananistan","adversaire":"Bananistan","win":{"news":"WORLD CHAMPIONS! Bananistan beaten, the country celebrates the title for a week."},"lose":{"news":"Final lost against Bananistan: the players are welcomed as heroes all the same."}}},"crises":{"mondial-attribution":{"title":"Suspicions over the World Cup award","description":"A newspaper reveals that members of the international federation received watches “of considerable sentimental value”.","choices":{"enquete":{"label":"Open an independent inquiry","description":"Transparency, and a few cold sweats.","news":"Independent inquiry opened: the watches are returned, honour is safe."},"nier":{"label":"Deny everything","description":"Make or break.","news":"“Courtesy gifts”: the defence draws smiles abroad."},"echarpes":{"label":"Give scarves to the investigators","description":"A flair for gifts, again.","news":"Investigators receive scarves in the national colours: they declare every one."}}},"mondial-stades":{"title":"Stadiums cost twice as much","description":"The national stadium is 100% over budget. The architect explains that “concrete has emotions”.","choices":{"payer":{"label":"Pay: national honour is at stake","description":"Magnificent stadiums, a flagging budget.","news":"The cheque is signed: the national stadium will even have a roof that opens to music."},"reduire":{"label":"Reduce stadium capacity","description":"Sober and a little sad.","news":"Smaller stadiums: the international federation frowns."},"sponsors":{"label":"Make the sponsors pay","description":"The stadium will be called “Yoghurt Arena”.","news":"Naming rights: the national stadium becomes the “Plain Yoghurt Arena”."}}},"mondial-selectionneur":{"title":"The national coach under fire from all sides","description":"Botched friendlies, disputed picks: the coach is the most criticised person in the country, just ahead of you.","choices":{"confiance":{"label":"Renew your confidence in him","description":"Stability before the tournament.","news":"The president backs the coach: “you don’t change captain before the storm”."},"demission":{"label":"Demand his resignation","description":"Popular, destabilising.","news":"The coach sacked: his assistant learns of the job by text message."},"neutre":{"label":"Stay neutral: “sport for the sportspeople”","description":"Cautious.","news":"“Sport for the sportspeople”: the president refuses to comment, except in private."}}},"mondial-ouverture":{"title":"The opening ceremony","description":"Two billion viewers. Margin for error: none.","choices":{"grandiose":{"label":"Grandiose show","description":"Dazzle the world.","news":"Grandiose ceremony: a dragon of light crosses the stadium, the planet applauds."},"sobre":{"label":"Sober, eco-friendly ceremony","description":"Elegant, less spectacular.","news":"Eco-friendly ceremony: illuminated bicycles and fireworks made of recycled paper."},"hymne":{"label":"The president sings the anthem solo","description":"Daring…","news":"The president strikes up the anthem: the stadium joins in, out of charity."}}},"mondial-hooligans":{"title":"Hooligans ransack a city centre","description":"A night of chaos: smashed windows, overturned terraces and a traumatised pigeon.","choices":{"expulsions":{"label":"Immediate expulsions","description":"Firmness.","news":"Special charters for hooligans: heading home, non-stop."},"alcool":{"label":"Ban alcohol around stadiums","description":"Effective, unpopular.","news":"Alcohol-free zones: bars serve grenadine syrup by the pint."},"fanzones":{"label":"Supervise the fan zones","description":"Channel the fervour.","news":"Supervised fan zones: more singing than smashing."}}},"mondial-tourisme":{"title":"Record influx of tourists","description":"Hotels full, restaurants packed, and supporters sleeping in parks, singing.","choices":{"hotels":{"label":"Open school dormitories to supporters","description":"Welcome everyone.","news":"Boarding schools host supporters: the dormitories have never been so noisy."},"taxe":{"label":"Raise the tourist tax","description":"Profitable.","news":"Tourist tax raised: supporters pay while singing, but less loudly."},"sourires":{"label":"National smile campaign","description":"Image first.","news":"“Smile, you’re the host” campaign: even ticket inspectors smile."}}},"mondial-greve":{"title":"Transport strike during the matches","description":"Metro drivers chose the day of the quarter-final to press their demands. A coincidence, they assure.","choices":{"ceder":{"label":"Give in to the demands","description":"The tournament goes on.","news":"Express deal: the metros run, drivers wear the national scarf."},"requisitionner":{"label":"Requisition the drivers","description":"Authority, tensions.","news":"Requisition: the metros run, reluctantly."},"navettes":{"label":"Free army shuttles","description":"A martial, friendly solution.","news":"The army carries supporters: khaki lorries become the stars of social media."}}},"mondial-cloture":{"title":"The closing ceremony","description":"The tournament ends. Cameras from all over the world are trained on the presidential box.","choices":{"discours":{"label":"A unifying speech","description":"Sport as glue.","news":"Closing speech: “This tournament reminded us that we know how to win together.”"},"fete":{"label":"Party across the whole country","description":"One last time.","news":"National night of celebration: fireworks light up every village."},"bilan":{"label":"Present a sober, costed review","description":"Seriousness pays abroad.","news":"Costed review presented: the international federation speaks of a “model organisation”."}}},"mondial-mascotte":{"title":"The official mascot causes a stir","description":"The mascot, a hedgehog in football boots, scares children and inspires comedians.","choices":{"changer":{"label":"Change the mascot","description":"Costly, soothing.","news":"The hedgehog is replaced by a smiling otter: children breathe again."},"assumer":{"label":"Own it with humour","description":"Self-mockery as a weapon.","news":"The president poses with the hedgehog: the photo becomes iconic."},"concours":{"label":"National contest for a new mascot","description":"Participatory.","news":"Mascot contest: 80,000 drawings received, 300 of them depicting the president."}}},"mondial-billets":{"title":"Sky-high ticket prices","description":"A ticket for the final costs a month’s salary. Supporters denounce a “World Cup for the rich”.","choices":{"plafonner":{"label":"Cap the prices","description":"Popular, costly for the State.","news":"Prices capped: the stands fill with real supporters."},"tirage":{"label":"Public ticket lottery","description":"Fair.","news":"Lottery: a 92-year-old grandmother wins two tickets for the final."},"marche":{"label":"Let the market decide","description":"Revenue first.","news":"Tickets at market price: VIP boxes overflow, the stands empty."}}},"mondial-blessure":{"title":"The team’s star is injured in training","description":"The playmaker twisted his ankle slipping on a banana skin. The country is in sporting mourning.","choices":{"kine":{"label":"Bring in the world’s best physio","description":"Everything for the ankle.","news":"The world’s best physio arrived by private jet: the ankle is responding well."},"soutien":{"label":"National message of support","description":"Unity is strength.","news":"The whole country sends get-well wishes: the ankle receives 2 million cards."},"cacher":{"label":"Hide the information","description":"It will come out eventually.","news":"The hidden injury is revealed by a photo of crutches: national controversy."}}},"mondial-pelouse":{"title":"The national stadium’s pitch has turned yellow","description":"Due to the drought, the pitch looks like straw. Foreign players complain of allergies.","choices":{"arroser":{"label":"Water heavily despite the drought","description":"Turf first.","news":"Intensive watering: the pitch turns green again, farmers see red."},"synthetique":{"label":"Switch to artificial turf","description":"Practical, criticised.","news":"Artificial turf laid: purists go into mourning."},"peindre":{"label":"Paint the pitch green","description":"Creative, debatable.","news":"Pitch painted green: so are the players’ socks."}}},"mondial-droits-tv":{"title":"Battle over TV rights","description":"A pay platform wants exclusive rights to the matches. Bistros threaten to broadcast the radio.","choices":{"gratuit":{"label":"Free broadcast for all","description":"Football is a common good.","news":"Matches free to air: the whole country watches together."},"vendre":{"label":"Sell to the highest bidder","description":"Guaranteed revenue.","news":"Rights sold: subscriptions soar, so does anger."},"ecrans":{"label":"Giant screens in public squares","description":"A party everywhere.","news":"Giant screens installed: every square becomes a grandstand."}}},"mondial-carbone":{"title":"The tournament’s carbon footprint denounced","description":"Charter flights, air-conditioned stadiums, diesel buses: environmentalists publish a carbon footprint “the size of a stadium”.","choices":{"compenser":{"label":"Offset the emissions","description":"Plant trees, lots of them.","news":"Carbon offsetting: a forest will be planted, with a “World Cup” sign."},"trains":{"label":"Special trains for supporters","description":"Useful and visible.","news":"Supporters’ trains: the singing goes from city to city."},"ignorer":{"label":"Ignore the criticism","description":"The show goes on.","news":"Criticism ignored: activists chain themselves to corner flags."}}},"mondial-fausse-note":{"title":"The presidential wrong note goes around the world","description":"The video of the president singing the anthem has 300 million views. An electro remix tops the charts.","choices":{"rire":{"label":"Laugh about it publicly","description":"Self-mockery saves the day.","news":"The president repeats his wrong note at a press conference: guaranteed hit."},"micro":{"label":"Blame the microphone","description":"Nobody believes it.","news":"“The microphone was faulty”: the sound engineer denies it live."}}}},"decisions":{"mondial-stades-sobres":{"title":"Sober, removable stadiums","description":"Removable stands and renovated rather than new stadiums: less prestige, much smaller bill.","news":"Removable stadiums: after the tournament, the stands will become park benches."},"mondial-centre":{"title":"Five-star training centre","description":"Give the national team the best preparation conditions (and raise its chances a little).","news":"Training centre opened: even the balls have their own room."},"mondial-fan-zones":{"title":"Giant fan zones in every city","description":"Bring the tournament to life everywhere: giant screens, concerts and supervised bars.","news":"Fan zones open: even villages of 200 people have their giant screen."}},"timeline":{"mondial-t1":{"note":{"from":"Your private secretary","text":"The federation sent the tournament schedule. I circled the final in red, and your diary in grey: you won’t have weekends any more."}},"mondial-t2":{"news":"Stadium sites run day and night: cranes are part of the landscape."},"mondial-t3":{"appel":{"from":"The president of the (fictional) International Football Federation","text":"Your country will be a wonderful host, I have no doubt. I only doubt the stadiums, the security and the transport. Otherwise, all is well."}},"mondial-t4":{"news":"The World Cup kicks off: the whole country has taken a day off, officially or not."},"mondial-t6":{"appel":{"from":"The captain of the national team","text":"Mr President, the team thanks you for your support. If you could avoid coming to the dressing room before matches, that would be even better."}},"mondial-t8":{"note":{"from":"Your private secretary","text":"Your suit for the closing ceremony is ready. I also prepared two speeches: one for victory, one for “the fine run”."}}},"objectives":{"mondial-ceremonie":{"label":"A beautiful finale","description":"At the closing ceremony: Popularity ≥ 66 and International ≥ 72."},"mondial-budget":{"label":"Budget discipline","description":"Budget ≥ 38 at the end of the tournament."},"mondial-parcours":{"label":"A memorable run","description":"The national team wins at least three matches."}},"endings":{"triomphe":{"title":"The perfect World Cup","text":"Praised organisation, sound accounts and a team that thrilled the country: this tournament will be remembered.","une":{"titre":"{LePays} pulls off its World Cup","chapo":"Exemplary organisation, budget held, heroic run: the president hails “a collective victory”."}},"succes":{"title":"A fine party","text":"The tournament ends with a flattering image and a happy country. The bills will come later.","une":{"titre":"World Cup: the host country shines","chapo":"The world praises the welcome; supporters leave with memories (and scarves)."}},"echec":{"title":"The spoilt party","text":"The tournament took place, but the country’s image or the president’s popularity did not last until the closing.","une":{"titre":"World Cup: a bitter taste","chapo":"Costly stadiums, deflated mood: analysts speak of “a tournament to forget”."}},"chute":{"title":"Red card","text":"Your government did not survive the tournament.","une":{"titre":"Red card for the president","chapo":"The World Cup goes on without him. The hedgehog mascot keeps its job."}}}}}'),t={standard:{title:"Standard term",pitch:"You arrive at the Élysée with a France neither better nor worse than usual: that is, in full contradiction, as always."},"france-en-faillite":{title:"Bankrupt France",pitch:"The coffers are empty, creditors are on the phone, and the treasurer has taken refuge under his desk. It will take courage, method and a little accounting poetry."},"apres-pandemie":{title:"After the pandemic",pitch:"The country recovers from a great health crisis: tired hospitals, a convalescing economy, people who finally want to go out. You must repair without saying “sorry for the inconvenience” every five minutes."},"cohabitation-imposee":{title:"Imposed cohabitation",pitch:"The legislative elections are lost: the opposition dominates the assembly, and the Prime Minister looks at you like a piece of furniture to refurbish. You will govern together, that is, treading on each other’s toes."},"pays-en-ebullition":{title:"Country at boiling point",pitch:"Marches everywhere, horns blaring in all directions, furious tweets. The country rumbles, but it listens to you — a little — before shouting louder."},"age-or-fragile":{title:"Fragile golden age",pitch:"All is well. A bit too well. Growth shines, polls purr, and advisers whisper that “it won’t last”. Enjoy, but keep an umbrella."},"crise-energetique":{title:"Energy crisis",pitch:"Energy prices soar, radiators are off, woollen jumpers become a national symbol. You must reassure, produce and invent a sobriety that doesn’t feel like punishment."},"majorite-eclatee":{title:"Shattered majority",pitch:"No group dominates the assembly. You must negotiate every comma, flatter every group, and never count votes before the corridors."},"bac-a-sable":{title:"Sandbox",pitch:"A pocket country to play with no consequences: no automatic defeat, free gauges to set, crises à la carte. Sandcastles are allowed."}},s={scenarios:e,situations:t};export{s as default,e as scenarios,t as situations};
